options.getOption:
// Seven days of rain over the area: one bar a day for the mean, a dot for the
// wettest cell. The day the map is drawing is in full colour and outlined; the
// others are dimmed behind it.
//
// Clicking a day moves the map to it: it writes the map's window
// (mapFrom/mapTo), which is what the map's own time bar writes; the map draws
// the newest date inside the window, and the one-day figure reads mapTo. There
// is nothing to clear: the map always draws one day.

// @constants begin
const FROM_VAR = 'mapFrom';
const TO_VAR = 'mapTo';
// written out, not built from the name: a variable spelled in the code is what
// makes Grafana redraw the chart when it changes, with no query re-run
const TO = '${mapTo}';
const WINDOW_MS = 12 * 3600 * 1000; // mapFrom = the day - 12 h: only that day falls inside
const MEAN_FIELD = 'media mm';
const MAX_FIELD = 'máximo mm';
const COLOR_MEAN = 'blue';
const COLOR_MAX = 'purple';
const UNIT = 'mm';
// @constants end

const chart = context.panel.chart;
const grafana = context.grafana;
const theme = grafana.theme;
const muted = theme.colors.text.secondary;
const color = (name) => theme.visualization.getColorByName(name);

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const num = (v) => (v == null || v === '' ? null : Number(v));
const times = col('time').map(Number);
const mean = col(MEAN_FIELD).map(num);
const max = col(MAX_FIELD).map(num);

// The day the map draws: the newest one at or before the end of its window,
// or the end of the dashboard's range before the map has published one.
const to = Date.parse(grafana.replaceVariables(TO));
const end = Number.isFinite(to) ? to : Number(grafana.replaceVariables('${__to}'));
let picked = -1;
times.forEach((t, i) => {
  if (t <= end && (picked < 0 || t > times[picked])) {
    picked = i;
  }
});

chart.off('click');
chart.on('click', (event) => {
  const t = times[event.dataIndex];
  if (!Number.isFinite(t)) {
    return;
  }
  grafana.locationService.partial(
    {
      ['var-' + FROM_VAR]: new Date(t - WINDOW_MS).toISOString(),
      ['var-' + TO_VAR]: new Date(t).toISOString(),
    },
    true
  );
});

const day = (ms) => new Date(ms).toISOString().slice(0, 10);
const label = (ms) => new Date(ms).toUTCString().slice(0, 11); // "Mon, 12 Oct"
const fmt = (v) => (v == null ? '–' : v.toFixed(1));

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 8, top: 34, bottom: 8, containLabel: true },
  legend: { top: 0, right: 8, textStyle: { color: muted }, selectedMode: false },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      return (
        `<b>${day(times[i])}</b><br/>mean <b>${fmt(mean[i])} ${UNIT}</b> · wettest cell ${fmt(max[i])} ${UNIT}` +
        `<br/><span style="opacity:.7">click to draw this day on the map</span>`
      );
    },
  },
  xAxis: {
    type: 'category',
    data: times.map(label),
    axisTick: { show: false },
    axisLabel: {
      color: muted,
      formatter: (v, i) => (i === picked ? '{on|' + v + '}' : v),
      rich: { on: { color: theme.colors.text.primary, fontWeight: 'bold' } },
    },
    axisLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  yAxis: [
    {
      type: 'value',
      name: 'mean ' + UNIT,
      nameTextStyle: { color: muted },
      axisLabel: { color: muted },
      splitLine: { lineStyle: { color: theme.colors.border.weak } },
    },
    {
      type: 'value',
      name: 'wettest cell ' + UNIT,
      nameTextStyle: { color: muted },
      axisLabel: { color: muted },
      splitLine: { show: false },
    },
  ],
  series: [
    {
      name: 'mean',
      type: 'bar',
      barWidth: '60%',
      cursor: 'pointer',
      itemStyle: { color: color(COLOR_MEAN) },
      data: mean.map((v, i) => ({
        value: v,
        itemStyle: {
          color: color(COLOR_MEAN),
          opacity: picked >= 0 && i !== picked ? 0.4 : 1,
          borderColor: i === picked ? theme.colors.text.primary : 'transparent',
          borderWidth: i === picked ? 2 : 0,
          borderRadius: [3, 3, 0, 0],
        },
      })),
      label: { show: true, position: 'top', color: muted, fontSize: 11, formatter: (p) => fmt(p.value) },
    },
    {
      name: 'wettest cell',
      type: 'line',
      yAxisIndex: 1,
      symbol: 'circle',
      symbolSize: 7,
      cursor: 'pointer',
      lineStyle: { type: 'dashed', width: 1, color: color(COLOR_MAX) },
      itemStyle: { color: color(COLOR_MAX) },
      data: max,
    },
  ],
};
